(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d', { alpha: false });
  const ui = Object.fromEntries(['day-label','time-label','coins','progress-fill','progress-count','target-card','target-name','target-hint','tool-name','zone-label','weather-label','toast','modal-backdrop','modal-title','modal-copy','modal-content'].map(id => [id, document.getElementById(id)]));
  const world = { width: 16, depth: 25, items: [], decor: [], player: { x: 0, z: 1.5, yaw: 0, pitch: 0 }, camera: { fov: 72 }, keys: new Set(), last: performance.now(), clock: 0, focus: null, toastTimer: 0, day: 1 };
  const saved = (() => { try { return JSON.parse(localStorage.getItem('little-haven-save') || '{}'); } catch { return {}; } })();
  const state = { coins: saved.coins || 0, cleaned: saved.cleaned || 0, day: saved.day || 1, upgrades: saved.upgrades || {}, decor: saved.decor || [], tools: saved.tools || ['basket'], selectedTool: saved.selectedTool || 'basket', total: 0, dailyBonus: false };
  world.day = state.day;
  const upgrades = [
    { id:'basket', name:'Woven basket', description:'A roomy basket for garden treasures.', price:0, emoji:'🧺', effect:'Your trusty starter tool.' },
    { id:'gloves', name:'Soft garden gloves', description:'A little extra reach for the tricky bits.', price:45, emoji:'🧤', effect:'Pickup range + 1.3m', range:1.3 },
    { id:'boots', name:'Dandelion boots', description:'Light feet for a spring in your step.', price:65, emoji:'🥾', effect:'Move 25% faster', speed:1.25 },
    { id:'rake', name:'Little leaf rake', description:'Sweep up a whole drift of leaves at once.', price:90, emoji:'🍂', effect:'Leaf piles reward +3 petals', leaf:3 },
    { id:'lantern', name:'Porch lantern', description:'A warm glow for your evening wander.', price:120, emoji:'🏮', effect:'Your yard feels a little brighter.', decor:'lantern' },
    { id:'birdbath', name:'Bluebird birdbath', description:'A lovely place for feathered visitors.', price:160, emoji:'🐦', effect:'A cheerful garden keepsake.', decor:'birdbath' }
  ];
  const rand = (seed => () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t ^= t + Math.imul(t ^ t >>> 7, 61 | t); return ((t ^ t >>> 14) >>> 0) / 4294967296; })(92817);
  function resize(){ const dpr=Math.min(devicePixelRatio||1,1.7); canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);world.w=innerWidth;world.h=innerHeight;world.focal=world.h/(2*Math.tan(world.camera.fov*Math.PI/360)); }
  addEventListener('resize',resize);resize();
  const primitives=[];
  function addPoly(points,color,stroke=null){const cx=points.reduce((s,p)=>s+p[0],0)/points.length,cz=points.reduce((s,p)=>s+p[2],0)/points.length;primitives.push({kind:'poly',points,color,stroke,cx,cz});}
  function box(x,y,z,w,h,d,color,top=color,side=null){const x0=x-w/2,x1=x+w/2,z0=z-d/2,z1=z+d/2,y0=y,y1=y+h;addPoly([[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1]],side||color);addPoly([[x0,y1,z1],[x1,y1,z1],[x1,y1,z0],[x0,y1,z0]],top);addPoly([[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0]],side||color);addPoly([[x1,y0,z0],[x1,y0,z1],[x1,y1,z1],[x1,y1,z0]],color);addPoly([[x0,y0,z1],[x0,y0,z0],[x0,y1,z0],[x0,y1,z1]],side||color);}
  function line(a,b,color,width=1){primitives.push({kind:'line',a,b,color,width,cx:(a[0]+b[0])/2,cz:(a[2]+b[2])/2});}
  function ellipseGround(x,z,rx,rz,y,color){const pts=[];for(let i=0;i<16;i++){const a=i/16*Math.PI*2;pts.push([x+Math.cos(a)*rx,y,z+Math.sin(a)*rz]);}addPoly(pts,color);}
  function makeScenery(){
    // The cottage and its mossy roof frame the far end of the lawn.
    box(0,0,14.4,8.2,3.8,1.1,'#d7c7a6','#e8d8b8','#bdab89');
    addPoly([[-4.45,3.8,13.8],[0,6.45,13.8],[4.45,3.8,13.8]],'#795f49');
    addPoly([[-4.45,3.8,13.8],[0,6.45,13.8],[0,6.45,15.0],[-4.45,3.8,15.0]],'#886a50');
    addPoly([[0,6.45,13.8],[4.45,3.8,13.8],[4.45,3.8,15],[0,6.45,15]],'#705941');
    box(-1.85,0,13.82,1.25,2.4,.08,'#6f8865','#78916d','#567353');
    box(1.7,1.05,13.79,1.05,1.15,.1,'#a8c1bd','#c7d6c3','#8fa99e');
    line([1.7,.48,13.71],[1.7,2.77,13.71],'#f0e2c6',.06);line([1.15,1.63,13.7],[2.25,1.63,13.7],'#f0e2c6',.06);
    // Fences with friendly scalloped-looking posts.
    for(let x=-8;x<=8;x+=1.2){if(Math.abs(x)<1.25)continue;box(x,0,-8, .13,1.45,.16,'#a98662','#c39e73','#93724f');box(x,0,12.6,.13,1.42,.16,'#a98662','#c39e73','#93724f');}
    for(const z of [-8,12.6]){box(0,.35,z,16,.14,.15,'#c7a274','#d4b283','#ae875e');box(0,.98,z,16,.14,.15,'#c7a274','#d4b283','#ae875e');}
    for(const z of [-7,-5.8,-4.6,-3.4,-2.2,-1,.2,1.4,2.6,3.8,5,6.2,7.4,8.6,9.8,11]){for(const x of [-8,8]){box(x,0,z,.15,1.38,.13,'#a98662','#c39e73','#93724f');}}
    for(const x of [-7.4,7.4]){box(x,.35,2.5,1.1,.14,.13,'#c7a274');box(x,.98,2.5,1.1,.14,.13,'#c7a274');}
    // Trees, fruit, flower beds and stepping stones.
    for(const [x,z,r] of [[-6.7,-5,1.1],[6.8,-6,.95],[-6.9,8,.85],[6.7,9,1.05]]){
      ellipseGround(x,z,.65,.6,.04,'#6d7950');box(x,.08,z,.35,2.15,.38,'#806347','#967354','#70543d');
      for(let i=0;i<5;i++){let ox=(rand()-.5)*r*1.35,oz=(rand()-.5)*r*1.3,oy=2.2+rand()*.95,rr=r*(.45+rand()*.27);const pts=[];for(let k=0;k<12;k++){let a=k*Math.PI/6;pts.push([x+ox+Math.cos(a)*rr,oy+Math.sin(a)*rr*.63,z+oz]);}addPoly(pts,['#5d8057','#6c8c5c','#789465','#668354'][i%4]);}
      if(rand()>.4)for(let f=0;f<3;f++){const fx=x+(rand()-.5)*1.3,fz=z+(rand()-.5)*1.2;ellipseGround(fx,fz,.07,.07,1.4,['#e7aa7b','#f4dd8b','#e3b2ba'][f]);}
    }
    for(const [x,z,w] of [[-6.4,-1.7,1.45],[6.35,-1.8,1.35],[-6.45,5.6,1.25],[6.4,5.4,1.25]]){
      box(x,0,z,w,.25,2.1,'#8f7455','#a98d65','#82694e');box(x,.24,z,w-.18,.12,1.94,'#554f37','#696445','#4d5238');
      for(let i=0;i<7;i++){const px=x+(rand()-.5)*(w-.25),pz=z+(rand()-.5)*1.75;line([px,0,pz],[px,.3+rand()*.12,pz],'#547b4c',.09);ellipseGround(px,pz,.075,.09,.38,['#dca6a0','#f0cf75','#d9b7d1','#f6e5ba'][i%4]);}
    }
    for(let i=0;i<8;i++){const z=9.8-i*1.25;ellipseGround(Math.sin(i*.62)*.55,z,.42,.3,.025,'#b7a68a');}
    // A potting bench and watering can make the space feel lived in.
    box(-4.3,0,10.7,2.2,.9,.55,'#8e6e4c','#b28b5e','#76583f');box(-4.3,.91,10.7,2.1,.12,.52,'#b98e5d');
    box(-4.8,1.03,10.7,.42,.22,.38,'#bf795a','#d2936e');box(-3.9,1.03,10.7,.42,.22,.38,'#d1b46c','#dfc987');
    // Garden lantern posts.
    for(const x of [-7.25,7.25]){box(x,0,3.2,.12,1.2,.12,'#665c42');box(x,.99,3.2,.33,.32,.33,'#f3d996','#ffe7a7','#a18a55');}
    // Hand-painted lawn flecks as subtle grounded color variation.
    for(let i=0;i<55;i++){const x=(rand()-.5)*14,z=-6+rand()*17;ellipseGround(x,z,.12+rand()*.3,.08+rand()*.25,.015,['#70945e','#78975e','#7c9a63','#6f905b'][i%4]);}
  }
  makeScenery();

  function project(p){const dx=p[0]-world.player.x,dz=p[2]-world.player.z,yaw=world.player.yaw;const depth=dx*Math.sin(yaw)+dz*Math.cos(yaw),side=dx*Math.cos(yaw)-dz*Math.sin(yaw);if(depth<=.08)return null;const cp=Math.cos(world.player.pitch),sp=Math.sin(world.player.pitch),vertical=(p[1]-1.62)*cp-depth*sp;return{x:world.w/2+side*world.focal/depth,y:world.h*.49-vertical*world.focal/depth,depth};}
  function drawPrimitive(o){if(o.kind==='poly'){const pts=o.points.map(project);if(pts.some(p=>!p))return;ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)ctx.lineTo(pts[i].x,pts[i].y);ctx.closePath();ctx.fillStyle=o.color;ctx.fill();if(o.stroke){ctx.strokeStyle=o.stroke;ctx.lineWidth=1;ctx.stroke();}}
    else{let a=project(o.a),b=project(o.b);if(!a||!b)return;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=o.color;ctx.lineWidth=Math.max(.6,o.width*world.focal/((a.depth+b.depth)/2));ctx.stroke();}}
  function drawGround(){const corners=[[-8,0,-8],[8,0,-8],[8,0,13],[-8,0,13]].map(project);if(corners.every(Boolean)){ctx.beginPath();ctx.moveTo(corners[0].x,corners[0].y);corners.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.closePath();const grad=ctx.createLinearGradient(0,world.h*.46,0,world.h);grad.addColorStop(0,'#70885a');grad.addColorStop(.28,'#78935f');grad.addColorStop(1,'#94a66d');ctx.fillStyle=grad;ctx.fill();}
    // Perspective seams in the neatly mown grass.
    ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#d5d19b';ctx.lineWidth=1;
    for(let x=-7.6;x<=7.6;x+=1.9){const a=project([x,.018,-8]),b=project([x,.018,13]);if(a&&b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}
    for(let z=-7;z<13;z+=2.6){const a=project([-8,.02,z]),b=project([8,.02,z]);if(a&&b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}ctx.restore();}
  function sky(){const g=ctx.createLinearGradient(0,0,0,world.h*.62);g.addColorStop(0,'#82989a');g.addColorStop(.48,'#bdc1a0');g.addColorStop(1,'#ead3a5');ctx.fillStyle=g;ctx.fillRect(0,0,world.w,world.h);const sx=world.w*.78,sy=world.h*.19;const glow=ctx.createRadialGradient(sx,sy,5,sx,sy,Math.min(world.w,world.h)*.23);glow.addColorStop(0,'rgba(255,235,174,.55)');glow.addColorStop(1,'rgba(255,237,192,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,world.w,world.h*.64);ctx.fillStyle='#ffe9b0';ctx.beginPath();ctx.arc(sx,sy,19,0,Math.PI*2);ctx.fill();}
  function drawScene(){sky();drawGround();primitives.sort((a,b)=>{const da=(a.cx-world.player.x)*Math.sin(world.player.yaw)+(a.cz-world.player.z)*Math.cos(world.player.yaw);const db=(b.cx-world.player.x)*Math.sin(world.player.yaw)+(b.cz-world.player.z)*Math.cos(world.player.yaw);return db-da;});for(const p of primitives)drawPrimitive(p);drawItems();drawHands();}

const kindInfo={litter:{name:'A bit of litter',icon:'🧻',reward:5},leaves:{name:'A pile of leaves',icon:'🍂',reward:4},weed:{name:'A cheeky weed',icon:'🌱',reward:3},apple:{name:'A fallen apple',icon:'🍎',reward:4}};
function seedItems(){world.items=[];const spots=[];for(let i=0;i<34;i++){let x,z,tries=0;do{x=(rand()-.5)*11.8;z=-5.4+rand()*15.7;tries++;}while(tries<30&&spots.some(p=>Math.hypot(p[0]-x,p[1]-z)<1.25));spots.push([x,z]);const roll=rand();const type=roll<.35?'litter':roll<.59?'leaves':roll<.83?'weed':'apple';world.items.push({id:`${state.day}-${i}`,x,z,type,active:true,phase:rand()*8});}world.total=world.items.length;updateProgress();}
seedItems();
function screenScale(p){return world.focal/p.depth;}
function drawItems(){const active=world.items.filter(i=>i.active).sort((a,b)=>{const da=(a.x-world.player.x)*Math.sin(world.player.yaw)+(a.z-world.player.z)*Math.cos(world.player.yaw);const db=(b.x-world.player.x)*Math.sin(world.player.yaw)+(b.z-world.player.z)*Math.cos(world.player.yaw);return db-da;});
  for(const it of active){const p=project([it.x,.13,it.z]);if(!p)continue;const s=screenScale(p);if(p.x< -100||p.x>world.w+100||p.y< -100||p.y>world.h+100)continue;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.globalAlpha=Math.min(1,Math.max(.3,1-p.depth/23));ctx.fillStyle='rgba(35,47,29,.22)';ctx.beginPath();ctx.ellipse(0,7,.35,.13,0,0,Math.PI*2);ctx.fill();
    if(it.type==='litter'){ctx.rotate(Math.sin(world.clock*.001+it.phase)*.07);ctx.fillStyle=it.id.charCodeAt(it.id.length-1)%2?'#e7d8b8':'#d7c6a9';ctx.beginPath();ctx.moveTo(-.22,-.13);ctx.lineTo(.18,-.2);ctx.lineTo(.28,.11);ctx.lineTo(-.17,.16);ctx.closePath();ctx.fill();ctx.strokeStyle='#c1ad8c';ctx.lineWidth=.025;ctx.stroke();ctx.fillStyle='#809d8a';ctx.fillRect(-.06,-.02,.16,.025);}
    if(it.type==='leaves'){for(let i=0;i<8;i++){const a=i*2.4+it.phase,r=.08+(i%3)*.07;ctx.fillStyle=['#bd774a','#d6984f','#b85d45','#d8b25e'][i%4];ctx.beginPath();ctx.ellipse(Math.cos(a)*r,Math.sin(a)*r*.45,.12,.065,a,0,Math.PI*2);ctx.fill();}}
    if(it.type==='weed'){ctx.strokeStyle='#587d4d';ctx.lineWidth=.055;for(let i=0;i<4;i++){const a=-.8+i*.48;ctx.beginPath();ctx.moveTo(0,.1);ctx.quadraticCurveTo(a*.14,-.12,a*.32,-.35+Math.abs(a)*.1);ctx.stroke();ctx.fillStyle='#739766';ctx.beginPath();ctx.ellipse(a*.26,-.32+Math.abs(a)*.1,.12,.055,a,0,Math.PI*2);ctx.fill();}}
    if(it.type==='apple'){ctx.fillStyle='#bd654d';ctx.beginPath();ctx.ellipse(0,.02,.15,.13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6b8052';ctx.beginPath();ctx.ellipse(.07,-.13,.09,.04,-.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#735b3d';ctx.lineWidth=.035;ctx.beginPath();ctx.moveTo(0,-.08);ctx.lineTo(.02,-.17);ctx.stroke();}
    if(world.focus===it){ctx.globalAlpha=1;ctx.strokeStyle='rgba(255,244,198,.9)';ctx.lineWidth=.025;ctx.beginPath();ctx.arc(0,0,.43+Math.sin(world.clock*.006)*.025,0,Math.PI*2);ctx.stroke();}ctx.restore();
  }
}
function drawHands(){// Quietly visible sleeves anchor the view as a first-person stroll.
  const w=world.w,h=world.h;ctx.save();ctx.globalAlpha=.96;
  const g=ctx.createLinearGradient(0,h*.82,0,h);g.addColorStop(0,'#738465');g.addColorStop(1,'#4e674e');ctx.fillStyle=g;
  ctx.beginPath();ctx.moveTo(0,h);ctx.lineTo(0,h*.925);ctx.quadraticCurveTo(w*.08,h*.87,w*.2,h*.94);ctx.lineTo(w*.3,h);ctx.closePath();ctx.fill();
  ctx.beginPath();ctx.moveTo(w,h);ctx.lineTo(w,h*.925);ctx.quadraticCurveTo(w*.92,h*.87,w*.8,h*.94);ctx.lineTo(w*.7,h);ctx.closePath();ctx.fill();
  ctx.fillStyle='#d6b38c';ctx.beginPath();ctx.ellipse(w*.17,h*.94,Math.min(w,h)*.039,Math.min(w,h)*.024,-.2,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(w*.83,h*.94,Math.min(w,h)*.039,Math.min(w,h)*.024,.2,0,Math.PI*2);ctx.fill();ctx.restore();
}
function updateFocus(){let best=null,bestDist=Infinity;const cx=world.w/2,cy=world.h*.49;const range=3.45+(state.upgrades.gloves?1.3:0);for(const it of world.items){if(!it.active)continue;const dist=Math.hypot(it.x-world.player.x,it.z-world.player.z);if(dist>range)continue;const p=project([it.x,.22,it.z]);if(!p)continue;const off=Math.hypot((p.x-cx)*.9,(p.y-cy));const radius=Math.max(38,Math.min(76,world.focal/p.depth*.32));if(off<radius&&dist<bestDist){best=it;bestDist=dist;}}
  world.focus=best;const card=ui['target-card'];if(best){const info=kindInfo[best.type];ui['target-name'].textContent=info.name;ui['target-hint'].textContent=best.type==='leaves'&&state.upgrades.rake?'Rake these up for a little extra':'Press E or click to tidy';card.classList.add('visible');}else card.classList.remove('visible');}
function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(world.toastTimer);world.toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100);}
function tidy(){if(!world.focus){if(document.pointerLockElement!==canvas&&matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.();return;}const it=world.focus,info=kindInfo[it.type];it.active=false;const extra=it.type==='leaves'&&state.upgrades.rake?3:0;state.coins+=info.reward+extra;state.cleaned++;save();updateHUD();updateProgress();toast(`${info.icon} ${info.name} tidied  ·  +${info.reward+extra} petals`);world.focus=null;
  if(world.items.every(i=>!i.active)){if(!state.dailyBonus){state.coins+=25;state.dailyBonus=true;}setTimeout(()=>{state.day++;world.day=state.day;state.dailyBonus=false;seedItems();save();updateHUD();toast(`A fresh morning in the garden · Day ${state.day}`);},1100);}}
function updateProgress(){const done=world.items.filter(i=>!i.active).length,total=world.items.length;ui['progress-count'].textContent=`${done} / ${total}`;ui['progress-fill'].style.width=`${total?done/total*100:0}%`;}
function updateHUD(){ui.coins.textContent=state.coins;ui['day-label'].textContent=`Day ${state.day}`;ui['time-label'].textContent=state.day%2?'8:15 AM':'9:05 AM';ui['tool-name'].textContent=state.selectedTool==='basket'?'Garden basket':state.selectedTool==='rake'?'Little leaf rake':'Garden gloves';ui['zone-label'].textContent=world.player.z>9?'BY THE COTTAGE':world.player.x>4?'SUNNY FLOWER BED':world.player.x< -4?'POTTING CORNER':'THE BACK GARDEN';}
function save(){try{localStorage.setItem('little-haven-save',JSON.stringify({coins:state.coins,cleaned:state.cleaned,day:state.day,upgrades:state.upgrades,decor:state.decor,tools:state.tools,selectedTool:state.selectedTool}));}catch{}}

  function showModal(title,copy,content){ui['modal-title'].textContent=title;ui['modal-copy'].textContent=copy;ui['modal-content'].innerHTML=content;ui['modal-backdrop'].classList.remove('hidden');}
  function closeModal(){ui['modal-backdrop'].classList.add('hidden');}
  function shop(){let html='<div class="shop-list">';for(const item of upgrades){const owned=item.price===0||state.upgrades[item.id];const afford=state.coins>=item.price;html+=`<div class="shop-item"><span class="shop-emoji">${item.emoji}</span><div class="shop-info"><b>${item.name}</b><small>${item.effect}</small></div><button class="buy-button" data-buy="${item.id}" ${owned||!afford?'disabled':''}>${owned?'Owned':`✦ ${item.price}`}</button></div>`;}html+='</div>';showModal('A few garden goodies','A little upgrade can make your tidy-up even sweeter.',html);document.querySelectorAll('[data-buy]').forEach(button=>button.addEventListener('click',()=>buyUpgrade(button.dataset.buy)));}
  function buyUpgrade(id){const item=upgrades.find(o=>o.id===id);if(!item||item.price===0||state.upgrades[id]||state.coins<item.price)return;state.coins-=item.price;state.upgrades[id]=true;if(id==='lantern'||id==='birdbath')placeDecor(id);if(id==='rake'||id==='gloves')state.selectedTool=id;save();updateHUD();shop();toast(`${item.name} added to your garden!`);}
  function placeDecor(id){if(state.decor.includes(id))return;state.decor.push(id);if(id==='lantern'){box(5.8,0,10.6,.12,1.5,.12,'#665c42');box(5.8,1.3,10.6,.35,.34,.35,'#f3d996','#ffe8a6','#a18a55');}else{ellipseGround(-1.3,11.3,.55,.44,.08,'#799a9b');ellipseGround(-1.3,11.3,.39,.3,.16,'#a8c9c2');ellipseGround(-1.3,11.3,.2,.16,.22,'#76a3a1');}}
  function journal(){const left=world.items.filter(i=>i.active).length;showModal('A little care goes a long way','Your own corner of the world, getting lovelier one small task at a time.',`<div class="journal-stats"><div class="stat-box"><b>${state.day}</b><small>garden day</small></div><div class="stat-box"><b>${state.cleaned}</b><small>things tidied</small></div><div class="stat-box"><b>${state.coins}</b><small>petals saved</small></div></div><div class="tip-line">${left?`There are <b>${left}</b> little bits left in today's garden. Your crosshair will find one when you get close.`:'Everything is looking lovely! A fresh garden day is on its way.'}<br><br><b>WASD</b> to wander · <b>mouse</b> to look · <b>E</b> or click to tidy · <b>T</b> to visit the garden shop.</div><div style="text-align:right;margin-top:12px"><button class="buy-button" id="reset-save" style="background:#a78a6c">Start a fresh save</button></div>`);document.getElementById('reset-save').addEventListener('click',()=>{if(confirm('Start over with a fresh garden? Your current progress will be erased.')){localStorage.removeItem('little-haven-save');location.reload();}});}
  document.getElementById('shop-button').addEventListener('click',shop);document.getElementById('menu-button').addEventListener('click',journal);document.getElementById('modal-close').addEventListener('click',closeModal);ui['modal-backdrop'].addEventListener('click',e=>{if(e.target===ui['modal-backdrop'])closeModal();});
