function resize(){const dpr=Math.min(devicePixelRatio||1,1.7);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);world.w=innerWidth;world.h=innerHeight;world.focal=world.h/(2*Math.tan(world.camera.fov*Math.PI/360));}addEventListener('resize',resize);resize();
const primitives=[];
function addPoly(points,color,stroke=null){primitives.push({kind:'poly',points,color,stroke,cx:points.reduce((s,p)=>s+p[0],0)/points.length,cz:points.reduce((s,p)=>s+p[2],0)/points.length});}
function box(x,y,z,w,h,d,color,top=color,side=null){const a=x-w/2,b=x+w/2,c=z-d/2,e=z+d/2,Y=y+h;addPoly([[a,y,c],[b,y,c],[b,y,e],[a,y,e]],side||color);addPoly([[a,Y,e],[b,Y,e],[b,Y,c],[a,Y,c]],top);addPoly([[a,y,c],[b,y,c],[b,Y,c],[a,Y,c]],side||color);addPoly([[b,y,c],[b,y,e],[b,Y,e],[b,Y,c]],color);addPoly([[a,y,e],[a,y,c],[a,Y,c],[a,Y,e]],side||color);}
function line(a,b,color,width=1){primitives.push({kind:'line',a,b,color,width,cx:(a[0]+b[0])/2,cz:(a[2]+b[2])/2});}
function ellipseGround(x,z,rx,rz,y,color){const pts=[];for(let i=0;i<16;i++){const a=i/16*Math.PI*2;pts.push([x+Math.cos(a)*rx,y,z+Math.sin(a)*rz]);}addPoly(pts,color);}
function makeScenery(){
 box(0,0,14.4,8.2,3.8,1.1,'#d7c7a6','#e8d8b8','#bdab89');addPoly([[-4.45,3.8,13.8],[0,6.45,13.8],[4.45,3.8,13.8]],'#795f49');addPoly([[-4.45,3.8,13.8],[0,6.45,13.8],[0,6.45,15],[-4.45,3.8,15]],'#886a50');addPoly([[0,6.45,13.8],[4.45,3.8,13.8],[4.45,3.8,15],[0,6.45,15]],'#705941');
 box(-1.85,0,13.82,1.25,2.4,.08,'#6f8865','#78916d','#567353');box(1.7,1.05,13.79,1.05,1.15,.1,'#a8c1bd','#c7d6c3','#8fa99e');line([1.7,.48,13.71],[1.7,2.77,13.71],'#f0e2c6',.06);line([1.15,1.63,13.7],[2.25,1.63,13.7],'#f0e2c6',.06);
 for(let x=-8;x<=8;x+=1.2){if(Math.abs(x)<1.25)continue;for(const z of [-8,12.6])box(x,0,z,.13,1.45,.16,'#a98662','#c39e73','#93724f');}
 for(const z of [-8,12.6]){box(0,.35,z,16,.14,.15,'#c7a274','#d4b283','#ae875e');box(0,.98,z,16,.14,.15,'#c7a274','#d4b283','#ae875e');}
 for(const z of [-7,-5.8,-4.6,-3.4,-2.2,-1,.2,1.4,2.6,3.8,5,6.2,7.4,8.6,9.8,11])for(const x of [-8,8])box(x,0,z,.15,1.38,.13,'#a98662','#c39e73','#93724f');
 for(const [x,z,r] of [[-6.7,-5,1.1],[6.8,-6,.95],[-6.9,8,.85],[6.7,9,1.05]]){ellipseGround(x,z,.65,.6,.04,'#6d7950');box(x,.08,z,.35,2.15,.38,'#806347','#967354','#70543d');for(let i=0;i<5;i++){const ox=(rand()-.5)*r*1.35,oz=(rand()-.5)*r*1.3,oy=2.2+rand()*.95,rr=r*(.45+rand()*.27),pts=[];for(let k=0;k<12;k++){const a=k*Math.PI/6;pts.push([x+ox+Math.cos(a)*rr,oy+Math.sin(a)*rr*.63,z+oz]);}addPoly(pts,['#5d8057','#6c8c5c','#789465','#668354'][i%4]);}if(rand()>.4)for(let f=0;f<3;f++)ellipseGround(x+(rand()-.5)*1.3,z+(rand()-.5)*1.2,.07,.07,1.4,['#e7aa7b','#f4dd8b','#e3b2ba'][f]);}
 for(const [x,z,w] of [[-6.4,-1.7,1.45],[6.35,-1.8,1.35],[-6.45,5.6,1.25],[6.4,5.4,1.25]]){box(x,0,z,w,.25,2.1,'#8f7455','#a98d65','#82694e');box(x,.24,z,w-.18,.12,1.94,'#554f37','#696445','#4d5238');for(let i=0;i<7;i++){const px=x+(rand()-.5)*(w-.25),pz=z+(rand()-.5)*1.75;line([px,0,pz],[px,.3+rand()*.12,pz],'#547b4c',.09);ellipseGround(px,pz,.075,.09,.38,['#dca6a0','#f0cf75','#d9b7d1','#f6e5ba'][i%4]);}}
 for(let i=0;i<8;i++)ellipseGround(Math.sin(i*.62)*.55,9.8-i*1.25,.42,.3,.025,'#b7a68a');box(-4.3,0,10.7,2.2,.9,.55,'#8e6e4c','#b28b5e','#76583f');box(-4.3,.91,10.7,2.1,.12,.52,'#b98e5d');box(-4.8,1.03,10.7,.42,.22,.38,'#bf795a','#d2936e');box(-3.9,1.03,10.7,.42,.22,.38,'#d1b46c','#dfc987');
 for(const x of [-7.25,7.25]){box(x,0,3.2,.12,1.2,.12,'#665c42');box(x,.99,3.2,.33,.32,.33,'#f3d996','#ffe7a7','#a18a55');}
 for(let i=0;i<55;i++)ellipseGround((rand()-.5)*14,-6+rand()*17,.12+rand()*.3,.08+rand()*.25,.015,['#70945e','#78975e','#7c9a63','#6f905b'][i%4]);
}makeScenery();
function project(p){const dx=p[0]-world.player.x,dz=p[2]-world.player.z,yaw=world.player.yaw,depth=dx*Math.sin(yaw)+dz*Math.cos(yaw),side=dx*Math.cos(yaw)-dz*Math.sin(yaw);if(depth<=.08)return null;const cp=Math.cos(world.player.pitch),sp=Math.sin(world.player.pitch),vertical=(p[1]-1.62)*cp-depth*sp;return{x:world.w/2+side*world.focal/depth,y:world.h*.49-vertical*world.focal/depth,depth};}
function drawPrimitive(o){if(o.kind==='poly'){const pts=o.points.map(project);if(pts.some(p=>!p))return;ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)ctx.lineTo(pts[i].x,pts[i].y);ctx.closePath();ctx.fillStyle=o.color;ctx.fill();if(o.stroke){ctx.strokeStyle=o.stroke;ctx.lineWidth=1;ctx.stroke();}}else{const a=project(o.a),b=project(o.b);if(!a||!b)return;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=o.color;ctx.lineWidth=Math.max(.6,o.width*world.focal/((a.depth+b.depth)/2));ctx.stroke();}}
