function tidy(){if(!world.focus){if(document.pointerLockElement!==canvas&&matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.();return;}const it=world.focus,info=kindInfo[it.type];it.active=false;const extra=it.type==='leaves'&&state.upgrades.rake?3:0;state.coins+=info.reward+extra;state.cleaned++;save();updateHUD();updateProgress();toast(`${info.icon} ${info.name} tidied  ·  +${info.reward+extra} petals`);world.focus=null;if(world.items.every(i=>!i.active)){if(!state.dailyBonus){state.coins+=25;state.dailyBonus=true;save();toast('A fully tidy garden · +25 petals!');}setTimeout(()=>{state.day++;world.day=state.day;state.dailyBonus=false;seedItems();save();updateHUD();toast(`A fresh morning in the garden · Day ${state.day}`);},1100);}}
