document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE'||e.code==='Space'){tidy();return;}if(e.code==='KeyT'){shop();return;}if(e.code==='Escape'){closeModal();return;}if(e.code==='Digit1'){state.selectedTool='basket';updateHUD();}if(e.code==='Digit2'&&state.upgrades.gloves){state.selectedTool='gloves';updateHUD();}if(e.code==='Digit3'&&state.upgrades.rake){state.selectedTool='rake';updateHUD();}world.keys.add(e.code);});document.addEventListener('keyup',e=>world.keys.delete(e.code));addEventListener('blur',()=>world.keys.clear());
