const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', e => errors.push(e.message));
await page.addInitScript(() => {
  const items = Array.from({ length: 34 }, (_, i) => ({ id: `1-${i}`, x: (i % 8) - 4, z: (i % 13) - 3, type: ['litter', 'leaves', 'weed', 'apple'][i % 4], active: i !== 0, phase: 0 }));
  localStorage.setItem('little-haven-save', JSON.stringify({ coins: 90, cleaned: 1, day: 1, upgrades: {}, decor: [], tools: ['basket'], selectedTool: 'basket', seenIntro: true, dailyBonus: false, items }));
});
await page.goto('http://127.0.0.1:3000/');
await page.waitForFunction(() => document.getElementById('progress-count').textContent === '0 / 34' || document.getElementById('progress-count').textContent === '1 / 34');
if (await page.locator('#progress-count').textContent() !== '1 / 34') throw new Error('Saved cleanup progress was not restored.');
await page.locator('#menu-button').click();
if (!(await page.locator('#modal-content').innerText()).includes('1')) throw new Error('Journal failed to open.');
await page.keyboard.press('Escape');
await page.locator('#shop-button').click();
if (await page.locator('[data-buy]').count() !== 6) throw new Error('Shop did not show all upgrades.');
await page.locator('[data-buy="gloves"]').click();
if (await page.locator('#coins').innerText() !== '45') throw new Error('Upgrade purchase did not deduct petals.');
await page.keyboard.press('Escape');
await page.reload();
if (await page.locator('#progress-count').innerText() !== '1 / 34') throw new Error('Cleanup progress did not persist after reload.');
if (await page.locator('#coins').innerText() !== '45') throw new Error('Wallet did not persist after reload.');
await page.locator('#menu-button').click();
if (!(await page.locator('#modal-content').innerText()).includes('garden day')) throw new Error('Journal did not reopen after reload.');
await page.keyboard.press('Escape');
await page.mouse.click(640, 400);
await page.keyboard.down('w');
await page.waitForTimeout(300);
await page.keyboard.up('w');
await page.waitForTimeout(300);
mkdirSync('/tmp/opencode', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/little-haven-latest.jpg', type: 'jpeg', quality: 82 });
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mobile.on('pageerror', e => errors.push(e.message));
await mobile.goto('http://127.0.0.1:3000/');
if (await mobile.locator('.touch-controls').isHidden()) throw new Error('Touch controls are hidden on mobile.');
if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
console.log(JSON.stringify({ status: 'passed', desktop: '1280x800 JPEG', mobile: '390x844 touch controls visible', checks: ['saved progress restore', 'journal', 'shop', 'upgrade purchase', 'wallet persistence', 'reload persistence', 'keyboard movement'], errors }));
await browser.close();

