import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', e => errors.push(e.message));
await page.addInitScript(() => {
  if (localStorage.getItem('little-haven-save')) return;
  const items = Array.from({ length: 34 }, (_, i) => ({
    id: `1-${i}`, x: i === 0 ? 0 : -5 + ((i * 3) % 11), z: i === 0 ? 4.8 : -5 + (Math.floor(i / 6) * 2.5),
    type: i === 0 ? 'litter' : ['litter', 'leaves', 'weed', 'apple'][i % 4], active: true, phase: 0
  }));
  localStorage.setItem('little-haven-save', JSON.stringify({ coins: 90, cleaned: 0, day: 1, upgrades: {}, decor: [], tools: ['basket'], selectedTool: 'basket', seenIntro: true, dailyBonus: false, items }));
});
await page.goto('http://127.0.0.1:3000/');
await page.waitForFunction(() => document.getElementById('progress-count').textContent === '0 / 34');
await page.locator('#menu-button').click();
if (!(await page.locator('#modal-content').innerText()).includes('garden day')) throw new Error('Journal failed to open.');
await page.keyboard.press('Escape');
await page.locator('#shop-button').click();
if (await page.locator('[data-buy]').count() !== 6) throw new Error('Shop did not show all upgrades.');
await page.locator('[data-buy="gloves"]').click();
if (await page.locator('#coins').innerText() !== '45') throw new Error('Upgrade purchase did not deduct petals.');
await page.keyboard.press('Escape');
await page.mouse.move(640, 400);
await page.mouse.down();
await page.mouse.up();
await page.mouse.move(640, 580);
await page.waitForTimeout(300);
if (await page.locator('#target-card').evaluate(el => !el.classList.contains('visible'))) throw new Error('Nearby garden litter was not targeted after looking down.');
await page.keyboard.press('e');
await page.waitForFunction(() => document.getElementById('progress-count').textContent === '1 / 34');
if (await page.locator('#coins').innerText() !== '50') throw new Error('Cleaning litter did not award petals.');
await page.keyboard.down('w');
await page.waitForTimeout(300);
await page.keyboard.up('w');
await page.reload();
if (await page.locator('#progress-count').innerText() !== '1 / 34') throw new Error('Cleanup progress did not persist after reload.');
if (await page.locator('#coins').innerText() !== '50') throw new Error('Wallet did not persist after reload.');
await page.locator('#menu-button').click();
if (!(await page.locator('#modal-content').innerText()).includes('garden day')) throw new Error('Journal did not reopen after reload.');
await page.keyboard.press('Escape');
mkdirSync('/tmp/opencode', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/little-haven-latest.jpg', type: 'jpeg', quality: 82 });
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mobile.on('pageerror', e => errors.push(e.message));
await mobile.goto('http://127.0.0.1:3000/');
if (await mobile.locator('.touch-controls').isHidden()) throw new Error('Touch controls are hidden on mobile.');
const moveButton = mobile.locator('[data-move="forward"]');
await moveButton.dispatchEvent('pointerdown', { pointerId: 7, pointerType: 'touch' });
await moveButton.dispatchEvent('pointerup', { pointerId: 7, pointerType: 'touch' });
if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
console.log(JSON.stringify({ status: 'passed', desktop: '1280x800 JPEG', mobile: '390x844 touch controls visible and responsive', checks: ['journal', 'shop', 'upgrade purchase', 'targeting and cleanup reward', 'keyboard movement', 'wallet and cleanup persistence after reload'], errors }));
await browser.close();

